const L = require('./lib_rtl.js');
const { P, H1, H2, BUL, NOTE, KEY, r, sub, sup, frac, par, EQ, table, doc, MathSum } = L;
const c = [];
const H3 = t => P(t, { size: 25, bold: true, color: '13603F', after: 70, before: 140, keepNext: true, align: L.AlignmentType.RIGHT });
const CAPT = t => P(t, { size: 21, bold: true, after: 60, keepNext: true, before: 120 });
const ANA = t => P('تحلیل: ' + t, { fill: 'FFF4EC', after: 140 });
const SUM = (title, items) => { c.push(H3(title)); items.forEach(([k, v]) => c.push(P(k + ': ' + v, { after: 60, indent: { right: 200 } }))); };

